// Calcula slots livres subtraindo eventos ocupados da janela solicitada.
const tenant = $('Get Tenant Calendar').first().json;
const input  = $('When Called by Workflow').first().json;
const eventos = $input.all().map(i => ({ start: new Date(i.json.start?.dateTime || i.json.start?.date), end: new Date(i.json.end?.dateTime || i.json.end?.date) })).filter(e => !isNaN(e.start));

const step  = (input.duration_min || 60) * 60 * 1000;
const from  = new Date(input.from).getTime();
const to    = new Date(input.to).getTime();
const bh    = tenant.bh || {};
const tz    = tenant.timezone || 'America/Sao_Paulo';

const weekdays = ['sun','mon','tue','wed','thu','fri','sat'];
function inBusinessHours(dateStart, dateEnd) {
  const wd = weekdays[dateStart.getDay()];
  const ranges = bh[wd] || [];
  if (!ranges.length) return false;
  const hhmm = d => d.getHours().toString().padStart(2,'0') + ':' + d.getMinutes().toString().padStart(2,'0');
  return ranges.some(r => { const [a,b] = r.split('-'); return hhmm(dateStart) >= a && hhmm(dateEnd) <= b; });
}
function overlaps(aS,aE) { return eventos.some(e => aS < e.end && aE > e.start); }

const slots = [];
for (let t = from; t + step <= to; t += step) {
  const s = new Date(t), e = new Date(t + step);
  if (!inBusinessHours(s, e)) continue;
  if (overlaps(s, e)) continue;
  slots.push({ start: s.toISOString(), end: e.toISOString() });
  if (slots.length >= 8) break;
}

// log tool_call
return [{ json: { ok: true, data: { slots, timezone: tz } } }];
